import{_ as n,l as r,o,c as s,v as a,p as i,x as d,d as S,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Seed / Doubao 公开信息","description":"","frontmatter":{"title":"Seed / Doubao 公开信息","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/seed-doubao.md","filePath":"llm/seed-doubao.md","lastUpdated":1789023840000}'),B={name:"llm/seed-doubao.md"};function A(h,e,g,c,E,u){const t=r("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="seed-doubao-公开信息" tabindex="-1">Seed / Doubao 公开信息 <a class="header-anchor" href="#seed-doubao-公开信息" aria-label="Permalink to &quot;Seed / Doubao 公开信息&quot;">​</a></h1><div class="epigraph"><p>豆包是产品名，Seed 是字节跳动的模型研究团队；能核对的结构数字来自 Seed 自己发表的思考模型报告、多模态论文与 1.6 技术博客，而不是豆包 App 的宣传句。</p><footer>—— ByteDance Seed，Seed-Thinking-v1.5 技术说明（2025）；Seed1.5-VL Technical Report；Seed1.6 官方博客</footer></div><p>字节跳动对外有三块牌子：<strong>豆包</strong>（C 端助手）、<strong>火山引擎 / 方舟</strong>（MaaS API）、<strong>Seed</strong>（研究与部分开源）。闭源通用对话模型的层数、专家数、预训练配比长期不进 arXiv；本篇只写团队已经公开的材料。已经落到纸面的包括：Seed-Thinking-v1.5（MoE <strong>200B 总 / 20B 激活</strong>）、Seed1.5-VL（视觉编码器 532M + MoE LLM <strong>20B 激活</strong>）、Seed1.6 博客（沿用稀疏 MoE，<strong>230B 总 / 23B 激活</strong>，256K，AdaCoT），以及后来开源的 Seed-OSS-36B。不要把 OSS-36B 的 512K 稠密检查点写成豆包 Pro 的内部结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>消费级助手要同时做中文闲聊、搜索增强、代码与推理，还要控延迟与单价。稠密放大激活参数会直接打爆 decode；字节在公开材料里把路线说成 <strong>稀疏 MoE</strong>：总参数撑知识，激活参数撑吞吐。问题是：哪些数字是 Seed 自己写的，哪些只是第三方「等效 4050 亿」之类的聚合站口径。后者一律不采用。</p><p>第二条分叉是 <strong>思考 / 不思考</strong>。可验证题（数学、代码）可以用结果奖励做 RL；写作等不可验证题要用成对比较。Seed-Thinking-v1.5 报告把这条数据与奖励分流写清楚了；豆包 App 里用户看到的「深度思考」开关，没有对应的开源 RL 配方，不能从 v1.5 报告反推 App 日更权重。</p><h3 id="产品名不等于检查点" tabindex="-1">产品名不等于检查点 <a class="header-anchor" href="#产品名不等于检查点" aria-label="Permalink to &quot;产品名不等于检查点&quot;">​</a></h3><p>火山方舟上的 <code>doubao-*</code>、<code>doubao-seed-*</code> 是 API 标识，随日期后缀换代。Seed1.6 博客给出的体验入口是 <code>doubao-seed-1-6-250615</code> 与 thinking 变体。写集成要钉模型 ID 与日期，不要写「豆包最新」这种不可复现的句子。</p><p><span class="marginnote">Seed1.6 博客写明：沿用 Seed1.5 稀疏 MoE 结论，预训练用 23B 激活、230B 总参数。这是 1.6 <strong>基座</strong>公开规格，不是对所有历史豆包版本的追溯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>Seed-Thinking-v1.5</strong>（2025 年 4 月前后技术说明）：智能推理模型，MoE 总 200B、激活 20B。可验证数据经人工筛选 → 模型过滤 → 多模型验证，保留约 10 万高难度题，并用答案整数化、离线沙箱等约束真实推理；不可验证数据从豆包 1.5 Pro 训练集剔除低价值样本，两两对比奖励。评测上团队另建超难数学集 BeyondAIME。基础设施公开 HybridFlow、流式推理系统 SRS（称训练速度约 3×）、张量/专家/序列三层并行。接口经火山引擎开放，权重未开源。</p><p><strong>Seed1.5-VL</strong>：视觉语言基座。532M 视觉编码器（SeedViT）+ MLP 适配器 + 激活 20B 的 MoE LLM。公开主张在 60 个公开基准中 38 项领先，并报 GUI / 游戏类智能体任务。方舟 ID 示例为 <code>doubao-1-5-thinking-vision-pro-250428</code>。本篇不把 VL 的视觉栈写成纯文本豆包。</p><h3 id="seed1-6-三阶段预训练与-adacot" tabindex="-1">Seed1.6：三阶段预训练与 AdaCoT <a class="header-anchor" href="#seed1-6-三阶段预训练与-adacot" aria-label="Permalink to &quot;Seed1.6：三阶段预训练与 AdaCoT&quot;">​</a></h3><p>Seed1.6 官方博客（而非完整 arXiv 总报告）给出可引用工序：预训练分三段。第一段纯文本，网页、书、论文、代码，规则加模型清洗、过滤、去重与采样。第二段 <strong>MMCT</strong>（Multimodal Mixed Continual Training）：提高学科、代码、推理密度，并混入视觉。第三段 <strong>LongCT</strong>：按长度区间把最大序列从 32K 抬到 <strong>256K</strong>。推理侧引入 <strong>AdaCoT</strong>（Adaptive Chain-of-Thought）：按题目难度自适应是否展开长思考，在效果与延迟之间折中。系列强调全生命周期融合多模态，而不只是后加一个投影层。</p><h3 id="开源-seed-oss-与闭源-api-分列" tabindex="-1">开源 Seed-OSS 与闭源 API 分列 <a class="header-anchor" href="#开源-seed-oss-与闭源-api-分列" aria-label="Permalink to &quot;开源 Seed-OSS 与闭源 API 分列&quot;">​</a></h3><p>2025 年 8 月 Seed 开源 <strong>Seed-OSS-36B</strong>（Base 含「含合成 / 无合成」两档，以及 Instruct），Apache 2.0。公开卡片：稠密 36B、GQA、SwiGLU、64 层、词表约 155K、上下文 <strong>512K</strong>、训练约 <strong>12T</strong>。这是另一条可本地下载的线，服务栈与方舟上的 Doubao-Seed 闭源 MoE <strong>不是</strong>同一权重。Seed2.0 模型卡（若引用）以评测方法与业务分布为主，官方仍不披露 2.0 的参数量与 RL 细节——缺数字就写「未公开」，不要用 1.6 的 230B 去填 2.0。</p>',16)),(o(),i(p,null,{default:d(()=>[l(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22Seed%20%E7%A0%94%E7%A9%B6%E7%BA%BF%22%5D%20--%3E%20T15%5B%22Thinking-v1.5%EF%BC%9A200B%2F20B%20MoE%22%5D%0A%20%20S%20--%3E%20VL%5B%22Seed1.5-VL%EF%BC%9A532M%20ViT%20%2B%2020B%20MoE%22%5D%0A%20%20S%20--%3E%20S16%5B%22Seed1.6%EF%BC%9A230B%2F23B%EF%BC%8CAdaCoT%EF%BC%8C256K%22%5D%0A%20%20S%20--%3E%20OSS%5B%22Seed-OSS-36B%20%E5%BC%80%E6%BA%90%E7%A8%A0%E5%AF%86%22%5D%0A%20%20T15%20--%3E%20API%5B%22%E7%81%AB%E5%B1%B1%E6%96%B9%E8%88%9F%20doubao%20%2F%20seed%20API%22%5D%0A%20%20VL%20--%3E%20API%0A%20%20S16%20--%3E%20API%0A%20%20API%20--%3E%20APP%5B%22%E8%B1%86%E5%8C%85%20C%20%E7%AB%AF%EF%BC%9A%E4%BA%A7%E5%93%81%E5%B0%81%E8%A3%85%EF%BC%8C%E5%86%85%E9%83%A8%E6%9D%83%E9%87%8D%E6%9C%AA%E5%85%AC%E5%BC%80%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[S(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公开 MoE 数字的机制含义很直接：激活 20B–23B 决定单 token 的矩阵乘与 KV 增长（再乘 GQA 等未在 1.6 博客展开的实现）；总 200B–230B 决定专家里能塞多少长尾知识。没有路由公式、没有共享专家个数，就不能把 DeepSeek-V3 的 loss-free 或混元的 recycle 安到 Seed 头上。</p><p>AdaCoT 把「是否思考」从用户开关部分内化成难度条件策略：简单问短答，难问才烧生成长度。机制上这是推理期计算分配，不是新的注意力核。LongCT 把窗口从 32K 堆到 256K，与 <a href="/llm/position-extrapolation">位置外推</a> 同类，但 Seed <strong>未</strong>公开 YaRN / NTK 的具体基数表。</p><p>Thinking-v1.5 把可验证 RL 与成对奖励拆开，是为了避免用数学 verifier 去打写作、或用偏好模型去打竞赛题。BeyondAIME 的存在说明内部认为 AIME 已不够分档；外部复现时若没有该集，不能宣称「复现了 Seed 的数学配方」。</p><p><span class="marginnote">豆包 1.5 Pro 在 Thinking-v1.5 报告里只作为不可验证数据的来源被点名。这不构成对 Doubao-1.5-Pro 架构的披露。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>禁止写入的内容：未公开的豆包总参数、专家数、预训练 token 精确配比、RLHF 系数、以及聚合站上的「4050 亿」一类来源不明数字。GUI 智能体分数属于 Seed1.5-VL 报告，不属于纯文本豆包。OSS-36B 的 512K 与 1.6 的 256K 不可混用。</p><p>接入以火山方舟当时模型列表为准；C 端豆包还有检索、安全过滤与产品编排，API 裸模型对不上 App 截图。安全与拒答策略未在本篇引用的技术说明里展开。Seed 博客把 Trae 等代码产品与豆包助手分列优化目标：前者偏代码推理与前端生成，后者偏指令稳健、长尾知识与长窗稳定——同一套 MoE 数字在不同后训练下会变成不同 API 名，不能互相替代评测。</p><p><span class="marginnote">写 Seed 只引用 seed.bytedance.com、官方 GitHub 与 arXiv。第三方「豆包参数量」表格默认不可信，除非能回溯到 Seed 自己的句子。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>豆包是产品，Seed 是研究团队；闭源通用模型只写已发表报告与博客。</li><li>已公开：Thinking-v1.5 为 200B/20B MoE；1.5-VL 为 532M 视觉 + 20B 激活；1.6 为 230B/23B、256K、AdaCoT。</li><li>Seed-OSS-36B 是开源稠密 512K 线，与方舟 Doubao-Seed 闭源 MoE 不是同一检查点。</li><li>出处：ByteDance Seed，<em>Seed-Thinking-v1.5</em> 技术说明；<em>Seed1.5-VL Technical Report</em>；Seed1.6 官方博客；Seed-OSS-36B 模型卡。</li></ul>',11))])}const m=n(B,[["render",A]]);export{b as __pageData,m as default};
